			                grp1Layout.setRowVisible(0, true);
			                grp1Layout.setRowVisible(1, false);
			                app.lookup("grp1").setLayout(grp1Layout);
			                
			                //사전/사후 작성자 수 셋팅
			                if (app.lookup("subList").getMetadata("BEFFAT_WRTR_COUNT")) {
			                    beffatwrtr = app.lookup("subList").getMetadata("BEFFAT_WRTR_COUNT");
			                }
			                if (app.lookup("subList").getMetadata("AFTFCT_WRTR_COUNT")) {
			                    aftfctwrtr = app.lookup("subList").getMetadata("AFTFCT_WRTR_COUNT");
			                }
			                app.lookup("opt7").value = '사전작성자 : ' + beffatwrtr + '명 / ' + "사후작성자 : " + aftfctwrtr + '명';
